"""RoboLab standard-mode control record; uses only public camera/proprioception API."""
import sys, json, pathlib, traceback, time
sys.path.insert(0, '/opt/tools')
import numpy as np
from rcb_client import Robot, EpisodeOver
r = Robot()
out = pathlib.Path('/app/runs'); out.mkdir(exist_ok=True)
(out/'spec.json').write_text(json.dumps(r.spec(), indent=2))
print(json.dumps({'ready':True,'status':r.status()}), flush=True)
i=0
for line in sys.stdin:
    try:
        cmd=json.loads(line); op=cmd.pop('op'); i+=1
        (out/'commands.jsonl').open('a').write(json.dumps({'index':i,'op':op,**cmd})+'\n')
        if op=='status':
            print(json.dumps(r.status()),flush=True); continue
        if op=='fk':
            print(json.dumps(r.fk(**cmd)),flush=True); continue
        if op=='ik':
            print(json.dumps(r.ik(**cmd)),flush=True); continue
        if op=='obs': res=r.get_obs(**cmd)
        elif op=='submit': res=r.submit(**cmd)
        else: raise ValueError(op)
        dest=out/f'{i:03d}';res.save(str(dest))
        print(json.dumps({'index':i,'path':str(dest),'meta':res.meta}), flush=True)
    except EpisodeOver as e:
        print(json.dumps({'episode_over':str(e),'status':r.status()}),flush=True)
    except Exception as e:
        traceback.print_exc()
        if isinstance(e, __import__('requests').exceptions.RequestException):
            print(json.dumps({'recovered_status':r.wait_ready()}),flush=True)
        else: print(json.dumps({'error':str(e)}),flush=True)
